            q("q2", f"SELECT {FORM_FAMILY} AS form_family, {ROUTE_FAMILY} AS route_family, COUNT(*) AS drug_count FROM drug dr WHERE dr.pharmaceutical_form != '' AND dr.administration_route != '' GROUP BY form_family, route_family", "For each drug form, how many are oral versus non-oral?"),
            q("q3", "SELECT CASE WHEN prescription_status LIKE '%prescription_only%' THEN 'prescription_only' ELSE 'other' END AS rx_status, CASE WHEN LOWER(storage_conditions) LIKE '%room temperature%' THEN 'room_temperature' ELSE 'other_storage' END AS storage_group, COUNT(*) AS drug_count FROM drug WHERE prescription_status != '' AND storage_conditions != '' GROUP BY rx_status, storage_group", "For prescription-only versus other drugs, how many are stored at room temperature versus under another condition?"),
            q("q4", f"SELECT {INST_TYPE_FAMILY} AS inst_type, {COUNTRY_FAMILY} AS country_family, COUNT(*) AS institution_count FROM institution i WHERE i.institution_type != '' AND i.institution_country != '' GROUP BY inst_type, country_family", "For each institution type, how many are in the USA versus outside the USA?"),
            q("q5", f"SELECT {FIELD_FAMILY} AS field_family, {COUNTRY_FAMILY} AS country_family, COUNT(*) AS institution_count FROM institution i WHERE i.research_fields != '' AND i.institution_country != '' GROUP BY field_family, country_family", "For labs in oncology, neuroscience, immunology/microbiology, clinical research, or another field, how many institutions are in the USA versus outside the USA?"),
            q("q6", f"SELECT {TYPE_FAMILY} AS type_family, CASE WHEN LOWER(d.pathogenesis) LIKE '%infectious%' THEN 'infectious_pathogenesis' WHEN d.pathogenesis != '' THEN 'other_pathogenesis' END AS path_group, COUNT(*) AS disease_count FROM disease d WHERE d.disease_type != '' AND d.pathogenesis != '' GROUP BY type_family, path_group", "For each disease-type family, how many have an infectious pathogenesis versus another recorded mechanism?"),
